<script setup lang="ts">
import { ref,computed,onMounted,onBeforeUnmount,watch } from 'vue';
import { ElMessage,ElMessageBox } from 'element-plus';
import ImportFieldEditor from '../components/ImportFieldEditor.vue';
import ImportSourceViewer from '../components/ImportSourceViewer.vue';
import { adminServices } from '../services/AdminServices';
import { RepositoryError } from '../repository/RepositoryError';
import { ImportJobStatus,type ImportCapabilities,type ImportJob,type ImportFile,type ImportRecognitionResult,type ContestPayload,type ImportDraftLink } from '../models/contracts';
import type { CatalogItem } from '../repository/CatalogRepository';
import { reviewFields,reviewStages,buildConfirmation,isDate,type FieldReview,type StageReview } from '../services/ImportReviewService';
const props=defineProps<{schoolId:string;schoolAdmin:boolean;initialTargetId?:string}>();
const emit=defineEmits<{'session-expired':[];busy:[value:boolean];'open-draft':[contestId:string]}>();
const repository=adminServices.getImports(),catalog=adminServices.getCatalog(),session=adminServices.getSession();
const capabilities=ref<ImportCapabilities|null>(null),error=ref(''),loading=ref(false),busy=ref(false),progress=ref('');
const mode=ref<'new'|'existing'>(props.schoolAdmin&&!props.initialTargetId?'new':'existing'),targetId=ref(''),target=ref<CatalogItem|null>(null),targets=ref<CatalogItem[]>([]),targetLoading=ref(false),targetKeyword=ref(''),targetPage=ref(1),targetTotal=ref(0);
const picked=ref<File[]>([]),uploaded=ref<ImportFile[]>([]),ticketIds=ref<string[]>([]),fileInput=ref<HTMLInputElement|null>(null),externalConsent=ref(false);
const jobs=ref<ImportJob[]>([]),page=ref(1),total=ref(0),status=ref<ImportJobStatus|''>(''),jobsLoading=ref(false);
const selected=ref<ImportJob|null>(null),result=ref<ImportRecognitionResult|null>(null),files=ref<ImportFile[]>([]),base=ref<ContestPayload|null>(null),baseEtag=ref<string|null>(null),targetBlocked=ref(''),detailLoading=ref(false),detailError=ref('');
const fields=ref<FieldReview[]>([]),stages=ref<StageReview[]>([]),reason=ref('根据上传材料核对并整理赛事资料'),applicableNote=ref(''),issueNotes=ref<Record<string,string>>({}),issueChecks=ref<Record<string,boolean>>({}),duplicateNote=ref(''),finalChecked=ref(false),focusEvidence=ref<string[]>([]),sections=ref(['basics','dates']),batchNote=ref(''),batchAttested=ref(false),confirmKey=ref(crypto.randomUUID()),jobKey=ref(crypto.randomUUID());
const groups=[{key:'basics',title:'基本信息',keys:['name','edition','category','scopeType','level']},{key:'dates',title:'整项日程与报名时间',keys:['regStart','regEnd','contestStart','contestEnd','publicityTime']},{key:'content',title:'参赛、奖项和说明',keys:['contestRequirement','reviewRules','awardSetting','material','entryMethod','contact','description']},{key:'sources',title:'来源与核对',keys:['sourceTitle','sourceOrg','sourceUrl','sourcePublishedAt','lastVerifiedAt']}];
let alive=true,listRun=0,detailRun=0,targetRun=0,uploadRun=0,poll:ReturnType<typeof setTimeout>|null=null,uploadController:AbortController|null=null;
const hasUnsaved=computed(()=>selected.value?.status==='待确认'&&(fields.value.some(f=>f.verified||f.note.trim())||stages.value.some(s=>s.verified||s.note.trim())));
const reviewed=computed(()=>fields.value.filter(f=>f.verified).length+stages.value.filter(s=>s.verified).length);
const canCreate=computed(()=>uploaded.value.length>0&&uploaded.value.length===picked.value.length&&!busy.value&&capabilities.value!==null&&(mode.value==='new'?props.schoolAdmin:!!target.value?.publishedVersion&&!target.value.workingVersion&&!target.value.contest.takedown));
const currentTarget=computed(()=>mode.value==='existing'?targetId.value||null:null);
const needsExternal=computed(()=>capabilities.value?.externalOcrEnabled&&uploaded.value.some(f=>f.requiresOcr));
const canConfirm=computed(()=>selected.value?.status==='待确认'&&!targetBlocked.value&&!busy.value&&!detailLoading.value&&!!result.value&&files.value.length===selected.value.fileIds.length);
watch([()=>uploaded.value.map(f=>f.fileId).join(','),currentTarget,externalConsent],()=>{jobKey.value=crypto.randomUUID();},{flush:'sync'});
watch(busy,value=>emit('busy',value));
function message(e:unknown){if(e instanceof RepositoryError&&e.code===401)emit('session-expired');return e instanceof Error?e.message:'操作失败，请重试';}
async function guard(){if(!await session.check()){emit('session-expired');return false;}return alive;}
function edited(){finalChecked.value=false;confirmKey.value=crypto.randomUUID();}
function stopPoll(){if(poll)clearTimeout(poll);poll=null;}
async function canLeave(){if(!busy.value&&!hasUnsaved.value&&!uploaded.value.length)return true;try{await ElMessageBox.confirm(busy.value?'离开会停止当前上传；已创建的后台任务会保留。是否离开？':'未保存的人工核对输入会丢失；已创建任务仍可从列表重新打开。是否离开？','离开文件导入',{confirmButtonText:'离开',cancelButtonText:'继续核对',type:'warning'});return true;}catch{return false;}}
defineExpose({canLeave});
async function loadCapabilities(){loading.value=true;error.value='';try{if(!await guard())return;const data=await repository.getCapabilities(props.schoolId);if(alive)capabilities.value=data;}catch(e){if(alive)error.value=message(e);}finally{if(alive)loading.value=false;}}
async function loadJobs(next=page.value){const id=++listRun;jobsLoading.value=true;try{if(!await guard())return;const data=await repository.listJobs({schoolId:props.schoolId,page:next,pageSize:10,status:status.value||undefined});if(!alive||id!==listRun)return;jobs.value=data.list;page.value=next;total.value=data.total;}catch(e){if(alive&&id===listRun)error.value=message(e);}finally{if(id===listRun)jobsLoading.value=false;}}
async function searchTargets(keyword:string,next=1){const id=++targetRun;targetKeyword.value=keyword;targetLoading.value=true;try{if(!await guard())return;const data=await catalog.list({keyword:keyword||undefined,page:next,pageSize:20});if(!alive||id!==targetRun)return;targets.value=next===1?data.list:targets.value.concat(data.list);targetPage.value=next;targetTotal.value=data.total;}catch(e){if(alive&&id===targetRun)error.value=message(e);}finally{if(id===targetRun)targetLoading.value=false;}}
async function selectTarget(id:string){targetId.value=id;target.value=null;if(!id)return;const run=++targetRun;targetLoading.value=true;try{if(!await guard())return;const item=await catalog.get(id);if(!alive||run!==targetRun)return;if(!targets.value.some(t=>t.contest.contestId===id))targets.value.unshift(item);target.value=item;}catch(e){if(alive)error.value=message(e);}finally{if(run===targetRun)targetLoading.value=false;}}
function targetLabel(item:CatalogItem){const version=item.publishedVersion||item.workingVersion;return (version?.payload.name||item.contest.contestId)+(item.workingVersion?'（已有工作版本）':!item.publishedVersion?'（尚未公开）':item.contest.takedown?'（已下架）':'');}
async function changeMode(){if(uploaded.value.length||picked.value.length){await clearFiles();if(uploaded.value.length)return;}target.value=null;targetId.value='';externalConsent.value=false;if(mode.value==='existing')await searchTargets('');}
function chooseFiles(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);if(files.length>10||files.some(f=>f.size<1||f.size>20*1024*1024)||files.reduce((n,f)=>n+f.size,0)>40*1024*1024){ElMessage.warning('最多10张图片；单文件20MiB、合计40MiB');input.value='';return;}const documents=files.filter(f=>/\.(pdf|docx)$/i.test(f.name));if(documents.length&&files.length!==1){ElMessage.warning('每次一份PDF/DOCX，或最多10张图片');input.value='';return;}picked.value=files;uploaded.value=[];ticketIds.value=[];externalConsent.value=false;error.value='';}
async function uploadFiles(){if(busy.value||!picked.value.length)return;if(mode.value==='existing'&&(!target.value?.publishedVersion||target.value.workingVersion||target.value.contest.takedown)){ElMessage.warning('请选择已公开且没有工作版本的已授权赛事');return;}const id=++uploadRun;busy.value=true;error.value='';uploadController=new AbortController();try{if(!await guard())return;const bound=currentTarget.value;for(let i=uploaded.value.length;i<picked.value.length;i++){progress.value='正在校验并上传第 '+(i+1)+' / '+picked.value.length+' 份材料…';const file=await adminServices.getImportFiles().upload(picked.value[i],props.schoolId,bound,uploadController.signal,fid=>{if(alive&&id===uploadRun)ticketIds.value.push(fid);});if(!alive||id!==uploadRun)return;uploaded.value.push(file);}progress.value='材料已接收，请确认识别方式后创建任务。';}catch(e){if(alive&&id===uploadRun)error.value=message(e);}finally{if(id===uploadRun){busy.value=false;uploadController=null;}}}
function cancelUpload(){uploadController?.abort();progress.value='已请求停止上传。已接收文件保留，可继续或清理。';}
async function clearFiles(){if(busy.value)return;busy.value=true;error.value='';try{if(!await guard())return;const failed:string[]=[];for(const id of [...new Set(ticketIds.value)]){if(!alive)return;try{await repository.deleteFile(id);}catch(e){failed.push(id);if(alive)error.value=message(e);}}if(!alive)return;if(failed.length){ticketIds.value=failed;ElMessage.warning('部分材料清理失败，请重试；不要在有任务引用时强行删除');return;}picked.value=[];uploaded.value=[];ticketIds.value=[];if(fileInput.value)fileInput.value.value='';externalConsent.value=false;progress.value='';}finally{if(alive)busy.value=false;}}
async function createJob(){if(!canCreate.value)return;if(needsExternal.value&&!externalConsent.value){ElMessage.warning('请先确认本次材料可发送至已配置的OCR服务');return;}busy.value=true;error.value='';try{if(!await guard())return;const job=await repository.createJob({schoolId:props.schoolId,targetContestId:currentTarget.value,fileIds:uploaded.value.map(f=>f.fileId),allowExternalOcr:needsExternal.value&&externalConsent.value||false,idempotencyKey:jobKey.value});if(!alive)return;picked.value=[];uploaded.value=[];ticketIds.value=[];if(fileInput.value)fileInput.value.value='';externalConsent.value=false;progress.value='任务已创建，识别在后台继续。';await loadJobs(1);await openJob(job);}catch(e){if(alive)error.value=message(e);}finally{if(alive)busy.value=false;}}
function installReview(job:ImportJob,data:ImportRecognitionResult,payload:ContestPayload|null){selected.value=job;result.value=data;base.value=payload;fields.value=reviewFields(data,payload);stages.value=reviewStages(data,payload);reason.value=job.targetContestId?'根据上传材料补充并核对已有赛事':'根据上传材料核对并整理赛事资料';applicableNote.value=payload?.applicableScope.applicableNote||'';issueNotes.value={};issueChecks.value={};duplicateNote.value='';finalChecked.value=false;confirmKey.value=crypto.randomUUID();batchNote.value='';batchAttested.value=false;focusEvidence.value=[];sections.value=['basics','dates'];}
async function openJob(row:ImportJob){if(selected.value?.jobId!==row.jobId&&hasUnsaved.value&&!await canLeave())return;stopPoll();const id=++detailRun;detailLoading.value=true;detailError.value='';selected.value=row;result.value=null;files.value=[];fields.value=[];stages.value=[];targetBlocked.value='';baseEtag.value=null;try{if(!await guard())return;const job=await repository.getJob(row.jobId);const metadata=await Promise.all(job.fileIds.map(id=>repository.getFile(id)));let payload:ContestPayload|null=null,etag:string|null=null,blocked='';if(job.targetContestId){const item=await catalog.get(job.targetContestId);payload=item.publishedVersion?.payload||null;etag=item.publishedVersion?.etag||null;if(item.workingVersion&&job.status!=='已转草稿')blocked='目标已有工作版本，请先在赛事维护处理，不能覆盖。';if(!item.publishedVersion||item.contest.takedown)blocked='目标没有有效公开版本或已下架，不能转入。';}const data=['待确认','已转草稿'].includes(job.status)?await repository.getResult(job.jobId):null;if(!alive||id!==detailRun)return;files.value=metadata;baseEtag.value=etag;targetBlocked.value=blocked;if(data)installReview(job,data,payload);else{selected.value=job;base.value=payload;}if(['排队中','识别中'].includes(job.status))schedulePoll(job.jobId,id);}catch(e){if(alive&&id===detailRun)detailError.value=message(e);}finally{if(id===detailRun)detailLoading.value=false;}}
function schedulePoll(id:string,run:number){stopPoll();poll=setTimeout(async()=>{if(!alive||run!==detailRun)return;try{const job=await repository.getJob(id);if(!alive||run!==detailRun)return;selected.value=job;if(['排队中','识别中'].includes(job.status))schedulePoll(id,run);else{await openJob(job);await loadJobs(page.value);}}catch(e){if(alive&&run===detailRun)detailError.value=message(e)+'；自动刷新已暂停，可手动重读任务。';}},1500);}
async function refreshSelected(){if(!selected.value)return;if(hasUnsaved.value&&!await canLeave())return;await openJob(selected.value);}
async function mutate(action:'retry'|'cancel'){if(!selected.value||busy.value)return;if(action==='cancel'){try{await ElMessageBox.confirm('取消任务后，未保存的核对输入会丢弃；已转成的草稿不会被删除。','取消识别任务');}catch{return;}}busy.value=true;detailError.value='';try{if(!await guard())return;const job=action==='retry'?await repository.retryJob(selected.value.jobId,{expectedEtag:selected.value.etag}):await repository.cancelJob(selected.value.jobId,{expectedEtag:selected.value.etag});if(!alive)return;await openJob(job);await loadJobs(page.value);}catch(e){if(alive)detailError.value=message(e);}finally{if(alive)busy.value=false;}}
function batchConfirm(){if(!batchAttested.value||!batchNote.value.trim()){ElMessage.warning('请先对照原件、填写核对说明并勾选确认');return;}for(const row of fields.value.filter(f=>!isDate(f.field))){if(row.mode!=='unknown'&&!row.value.trim())continue;row.verified=true;if(row.mode!=='unknown'&&!row.note.trim())row.note=batchNote.value.trim();}edited();ElMessage.success('非日期项已记录核对；日期和各阶段仍需逐项勾选。');}
function addStage(){stages.value.push({field:'stageDate' as StageReview['field'],label:'新增阶段',stage:'',fixedName:false,sourceUrl:'',mode:'manual',value:'',candidateId:null,evidenceIds:[],note:'',verified:false,existingValue:null,candidates:[]});edited();}
function focus(ids:string[]){focusEvidence.value=ids.slice();}
function useSource(stage:StageReview){const row=fields.value.find(f=>f.field==='sourceUrl');if(!row?.verified||!/^https:\/\//.test(row.value)){ElMessage.warning('请先确认有效的HTTPS原通知链接');return;}stage.sourceUrl=row.value;stage.verified=false;edited();}
async function chooseDuplicate(id:string){try{await ElMessageBox.confirm('当前任务不能直接更换目标。取消当前任务后，请重新选择原文件，为该已有赛事建立补充任务。','改为补充已有赛事');}catch{return;}if(!selected.value)return;busy.value=true;try{const cancelled=await repository.cancelJob(selected.value.jobId,{expectedEtag:selected.value.etag});if(!alive)return;await openJob(cancelled);mode.value='existing';await selectTarget(id);ElMessage.info('目标已选择，请重新选择原文件并上传。');await loadJobs(1);}catch(e){if(alive)detailError.value=message(e);}finally{if(alive)busy.value=false;}}
async function saveDraft(){if(!canConfirm.value||!selected.value||!result.value)return;detailError.value='';let request;try{if(result.value.issues.some(i=>i.severity==='需确认'&&!issueChecks.value[i.issueId]))throw Error('请逐项勾选问题已处理，并填写说明');request=buildConfirmation({job:selected.value,result:result.value,fields:fields.value,stages:stages.value,base:base.value,expectedPublishedEtag:baseEtag.value,reason:reason.value,applicableNote:applicableNote.value,issueNotes:issueNotes.value,duplicateNote:duplicateNote.value,key:confirmKey.value,finalChecked:finalChecked.value});}catch(e){detailError.value=message(e);return;}try{await ElMessageBox.confirm('将已核对内容保存为普通草稿。学生端内容暂不改变；之后需在赛事维护提交并由校级管理员审核。','保存识别草稿',{confirmButtonText:'保存草稿',cancelButtonText:'继续核对'});}catch{return;}busy.value=true;try{if(!await guard())return;const fresh=await repository.getJob(selected.value.jobId);if(!alive)return;if(fresh.status==='已转草稿'&&fresh.draftLink){selected.value=fresh;ElMessage.success('此前请求已成功保存，已恢复草稿关联');return;}if(fresh.etag!==selected.value.etag)throw new RepositoryError(409,'任务已变化，输入已保留，请重新载入核对');const link=await repository.confirmDraft(selected.value.jobId,request);if(!alive)return;selected.value={...selected.value,status:ImportJobStatus.Value3,draftLink:link};finalChecked.value=false;ElMessage.success('草稿已保存，尚未提交或公开');await loadJobs(page.value);}catch(e){if(alive)detailError.value=message(e)+'；输入已保留。网络失败可用相同内容再次保存；修改后会使用新的请求标识。';}finally{if(alive)busy.value=false;}}
watch(()=>props.initialTargetId,id=>{if(id&&id!==targetId.value){mode.value='existing';void selectTarget(id);}},{immediate:true});
onMounted(()=>{void loadCapabilities();void loadJobs(1);if(!props.initialTargetId)void searchTargets('');});
onBeforeUnmount(()=>{alive=false;listRun++;detailRun++;targetRun++;uploadRun++;stopPoll();uploadController?.abort();emit('busy',false);});
</script>
<template>
 <section class="import-panel">
  <div class="intro"><div><h2>从文件整理赛事</h2><p>上传通知或照片，核对识别内容，再保存为草稿。</p></div><el-tag>人工确认 · 校级审核后公开</el-tag></div>
  <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
  <el-alert v-if="!capabilities&&!loading" title="文件导入服务尚未就绪。请确认后端已更新并完成004迁移，然后重试。" type="warning" :closable="false"/>
  <div class="upload-card" v-loading="loading">
   <div class="card-title"><h3>1. 选择目标与材料</h3><el-button @click="loadCapabilities" :disabled="busy">检查服务</el-button></div>
   <el-radio-group v-model="mode" :disabled="busy||uploaded.length>0||picked.length>0" @change="changeMode"><el-radio-button v-if="schoolAdmin" value="new">新建赛事</el-radio-button><el-radio-button value="existing">补充已有赛事</el-radio-button></el-radio-group>
   <p v-if="!schoolAdmin" class="muted">负责人仅能补充已分配赛事，新赛事由校级管理员创建后分配。</p>
   <div v-if="mode==='existing'" class="target-picker"><el-select v-model="targetId" filterable remote :remote-method="searchTargets" :loading="targetLoading" :disabled="busy||uploaded.length>0||picked.length>0" placeholder="搜索可维护的已公开赛事" aria-label="导入目标赛事" @change="selectTarget"><el-option v-for="item in targets" :key="item.contest.contestId" :label="targetLabel(item)" :value="item.contest.contestId" :disabled="!!item.workingVersion||!item.publishedVersion||!!item.contest.takedown"/></el-select><el-button v-if="targets.length<targetTotal" :disabled="targetLoading" @click="searchTargets(targetKeyword,targetPage+1)">再载入20项</el-button></div>
   <el-alert v-if="target&&(target.workingVersion||!target.publishedVersion||target.contest.takedown)" title="该赛事已有工作版本、未公开或已下架，请先在赛事维护处理。" type="warning" :closable="false"/>
   <label class="file-drop"><strong>选择 PDF、Word 通知或赛事照片</strong><span>每次一份 PDF / DOCX，或最多10张 JPEG、PNG、WebP。单文件20MiB，合计40MiB。</span><input ref="fileInput" type="file" multiple accept=".pdf,.docx,.jpg,.jpeg,.png,.webp" :disabled="busy||uploaded.length>0||!capabilities||(mode==='existing'&&!target?.publishedVersion)" @change="chooseFiles"/></label>
   <p class="muted">一份材料只整理一项赛事。请先遮挡与赛事无关的个人信息；材料保存在管理端私有范围。</p>
   <ul v-if="picked.length" class="file-list"><li v-for="(file,index) in picked" :key="index"><span>{{file.name}} · {{(file.size/1024).toFixed(1)}} KiB</span><el-tag :type="uploaded[index]?'success':'info'">{{uploaded[index]?'已接收':'待上传'}}</el-tag></li></ul>
   <div class="button-row"><el-button type="primary" :loading="busy&&!!uploadController" :disabled="busy||!picked.length||uploaded.length===picked.length||!capabilities" @click="uploadFiles">{{uploaded.length?'继续上传剩余材料':'上传并检查材料'}}</el-button><el-button v-if="uploadController" @click="cancelUpload">停止上传</el-button><el-button :disabled="busy||!picked.length" @click="clearFiles">清理已选材料</el-button></div>
   <p v-if="progress" class="progress" role="status">{{progress}}</p>
   <div v-if="uploaded.length" class="recognition-choice"><template v-if="needsExternal"><el-alert :title="'材料包含照片或扫描页，将发送至后端配置的视觉OCR服务（'+capabilities?.ocrModel+'）。可能产生费用，结果仍需人工核对。'" type="warning" :closable="false"/><el-checkbox v-model="externalConsent" :disabled="busy">我确认本次材料可发送至已配置的识别服务</el-checkbox></template><p v-else class="muted">{{uploaded.some(f=>f.requiresOcr)?'当前只启用本地文字提取：照片/扫描页会提示需要配置OCR，不会生成演示内容。':'文字在本地提取；不会将本次文字材料发送到第三方。'}}</p><el-button type="success" :loading="busy&&!uploadController" :disabled="!canCreate||(needsExternal&&!externalConsent)" @click="createJob">创建识别任务</el-button></div>
  </div>
  <section class="task-card"><div class="card-title"><h3>2. 识别任务</h3><div class="button-row"><el-select v-model="status" clearable placeholder="全部任务状态" aria-label="任务状态筛选" @change="loadJobs(1)"><el-option v-for="s in Object.values(ImportJobStatus)" :key="s" :label="s" :value="s"/></el-select><el-button :loading="jobsLoading" @click="loadJobs(page)">刷新列表</el-button></div></div>
   <el-table :data="jobs" v-loading="jobsLoading" empty-text="暂无识别任务"><el-table-column label="创建时间" min-width="180"><template #default="{row}">{{new Date(row.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</template></el-table-column><el-table-column label="用途" min-width="160"><template #default="{row}">{{row.targetContestId?'补充已有赛事':'新建赛事'}} · {{row.fileIds.length}} 份材料</template></el-table-column><el-table-column prop="status" label="状态" width="120"/><el-table-column label="识别次数" width="100"><template #default="{row}">{{row.attempt}} / 3</template></el-table-column><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" :disabled="busy" @click="openJob(row)">{{row.status==='待确认'?'对照并确认':'查看任务'}}</el-button></template></el-table-column></el-table>
   <el-pagination layout="prev,pager,next,total" background :total="total" :page-size="10" :current-page="page" :disabled="jobsLoading" @current-change="loadJobs"/>
  </section>
  <section v-if="selected" class="review-card" v-loading="detailLoading"><div class="card-title"><div><h3>3. {{selected.status==='已转草稿'?'草稿已保存':'对照原文并确认'}}</h3><p class="muted">{{selected.targetContestId?'补充任务：保持原赛事ID，公开版本审核前不变。':'新建任务：不会直接公开。'}} · {{selected.status}}</p></div><div class="button-row"><el-button :disabled="busy" @click="refreshSelected">重新载入任务</el-button><el-button v-if="selected.status==='失败'" :disabled="busy||selected.attempt>=3" @click="mutate('retry')">重试识别</el-button><el-button v-if="['排队中','识别中','待确认','失败'].includes(selected.status)" :disabled="busy" @click="mutate('cancel')">取消任务</el-button></div></div>
   <el-alert v-if="detailError" :title="detailError" type="error" :closable="false"/>
   <el-alert v-if="targetBlocked" :title="targetBlocked" type="warning" :closable="false"/>
   <el-alert v-if="selected.failureMessage" :title="selected.failureMessage" type="warning" :closable="false"/>
   <p v-if="['排队中','识别中'].includes(selected.status)" class="progress">{{selected.status==='排队中'?'正在等待处理':'正在提取材料中的文字和日程'}}，此页每1.5秒刷新。离开页面后任务仍会保留。</p>
   <div v-if="selected.status==='已转草稿'&&selected.draftLink" class="saved-box"><h4>已生成草稿 v{{selected.draftLink.versionNo}}</h4><p>识别任务已关联草稿，无需再次保存。可前往赛事维护补全公开来源和其他资料，再提交校级审核。</p><el-button type="primary" @click="emit('open-draft',selected.draftLink.contestId)">前往赛事维护</el-button></div>
   <div v-if="result&&selected.status==='待确认'" class="review-layout">
    <div class="review-form">
     <el-alert title="识别内容可能出错。逐项对照原件；未公布的时间保持未知，不能把作品截止或初赛结束当成整项比赛结束。" type="warning" :closable="false"/>
     <section v-if="result.duplicates.length" class="notice-box"><h4>发现可访问的疑似重复赛事</h4><p class="muted">仅名称相似，不自动合并。已有赛事需从固定目标重新建立补充任务。</p><article v-for="duplicate in result.duplicates" :key="duplicate.contestId"><strong>{{duplicate.name}}</strong><span> · {{duplicate.edition||'届次未填'}}</span><el-button v-if="!selected.targetContestId" link type="primary" :disabled="busy" @click="chooseDuplicate(duplicate.contestId)">取消本任务并改为补充此赛事</el-button></article><el-input v-if="!selected.targetContestId" v-model="duplicateNote" type="textarea" placeholder="如果确认仍需新建，请说明与候选赛事的区别" @input="edited"/></section>
     <section class="batch-box"><h4>辅助核对</h4><el-input v-model="batchNote" placeholder="填写本次原文核对依据，例如第1页署名与正文已核对" :disabled="busy"/><el-checkbox v-model="batchAttested" :disabled="busy">我已逐项对照原件检查下面的非日期字段</el-checkbox><el-button :disabled="busy||!batchAttested||!batchNote.trim()" @click="batchConfirm">记录非日期项核对（日期仍须逐项确认）</el-button></section>
     <p class="review-count">已核对 {{reviewed}} / {{fields.length+stages.length}} 项</p>
     <el-collapse v-model="sections"><el-collapse-item v-for="group in groups" :key="group.key" :name="group.key" :title="group.title+' · '+fields.filter(f=>group.keys.includes(f.field)&&f.verified).length+'/'+group.keys.length"><div class="field-stack"><ImportFieldEditor v-for="row in fields.filter(f=>group.keys.includes(f.field))" :key="row.field" :row="row" :evidence="result.evidence" :disabled="busy" @changed="edited" @evidence="focus"/></div></el-collapse-item></el-collapse>
     <section class="stage-box"><div class="card-title"><h4>分阶段日程</h4><el-button :disabled="busy" @click="addStage">添加阶段</el-button></div><p class="muted">报名、初赛、复赛、决赛、作品提交分别确认。阶段不明确的原始候选可保留未知，再手工添加明确阶段。</p><article v-for="(stage,index) in stages" :key="index" class="stage-item"><div class="button-row"><el-input v-model="stage.stage" :disabled="busy||stage.fixedName" placeholder="阶段名称，例如初赛开始、论文提交截止" @input="stage.verified=false;edited()"/><el-button v-if="!stage.fixedName" :disabled="busy" @click="stages.splice(index,1);edited()">移除此新增阶段</el-button></div><ImportFieldEditor :row="stage" :evidence="result.evidence" :disabled="busy" @changed="edited" @evidence="focus"/><el-input v-model="stage.sourceUrl" :disabled="busy" placeholder="公开HTTPS官方来源（没有则留空，保存为待核对的上传资料说明）" @input="stage.verified=false;edited()"/><el-button link type="primary" :disabled="busy" @click="useSource(stage)">使用已确认的原通知链接</el-button></article><p v-if="!stages.length" class="muted">暂未提取独立阶段，不自动推断。</p></section>
     <section class="notice-box"><h4>参赛范围与修改原因</h4><el-input v-model="applicableNote" type="textarea" :disabled="busy" placeholder="适用对象补充说明；原赛事的学院、专业、年级等结构化限制将保留" @input="edited"/><p class="muted">{{base?'沿用当前公开版本的第二课堂标记与依据，不根据识别文字自动加分。':'第二课堂默认待确认，不自动承诺学分或学校认定。'}}</p><el-input v-model="reason" :disabled="busy" maxlength="2000" placeholder="修改原因（必填）" @input="edited"/></section>
     <section class="issue-box"><h4>识别问题与处理说明</h4><article v-for="issue in result.issues" :key="issue.issueId"><el-tag :type="issue.severity==='阻断'?'danger':issue.severity==='需确认'?'warning':'info'">{{issue.severity}} · {{issue.code}}</el-tag><p>{{issue.message}}</p><template v-if="issue.severity==='需确认'"><el-input v-model="issueNotes[issue.issueId]" type="textarea" :disabled="busy" placeholder="说明如何核对、修正或保留未知" maxlength="2000" @input="edited"/><el-checkbox v-model="issueChecks[issue.issueId]" :disabled="busy" @change="edited">已对照原件处理此问题</el-checkbox></template></article></section>
     <div class="confirm-footer"><el-checkbox v-model="finalChecked" :disabled="busy">我已核对原件、日期与阶段、参赛范围和第二课堂信息；本次仅保存草稿。</el-checkbox><el-button type="primary" size="large" :loading="busy" :disabled="!canConfirm||!finalChecked" @click="saveDraft">保存为赛事草稿</el-button><p class="muted">如暂缺公开来源或其他发布资料，可先保存，再在赛事维护补齐并提交审核。</p></div>
    </div>
    <div class="source-column"><ImportSourceViewer :key="selected.jobId" :files="files" :evidence="result.evidence" :school-id="schoolId" :focus-evidence-ids="focusEvidence" @session-expired="emit('session-expired')"/></div>
   </div>
  </section>
 </section>
</template>
<style scoped>
