;border-radius:10px;background:#f5f8fc}.stage-item>.button-row{flex-wrap:nowrap}.issue-box article{padding:12px 0;border-bottom:1px solid #e2e8f0}.issue-box p{font-size:13px;line-height:1.7}.confirm-footer{display:grid;gap:14px;padding:18px;background:#eff5ff;border:1px solid #b7cbed;border-radius:12px}.confirm-footer .el-checkbox{height:auto;white-space:normal;line-height:1.6}.saved-box{padding:18px;border:1px solid #9acbb1;background:#f1faf5;border-radius:12px}.saved-box h4{margin:0 0 8px}.saved-box p{font-size:13px;line-height:1.8}.el-pagination{margin-top:12px}@media(max-width:1000px){.review-layout{grid-template-columns:1fr}.source-column{position:static;grid-row:1}.source-column :deep(.page-text){max-height:260px}}@media(max-width:640px){.upload-card,.task-card,.review-card{padding:14px}.target-picker{flex-direction:column}.stage-item>.button-row{flex-wrap:wrap}}
